<style>
:root{--navy:#062d66;--blue:#1682df;--red:#df0b27;--green:#159a67;--amber:#d99018;--bg:#f3f6fb;--line:#dfe7f1;--muted:#8190a3}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--navy);font-family:Arial,sans-serif}.wrap{width:100%;max-width:none;margin:0;padding:14px clamp(14px,1.35vw,26px)}.panel{background:#fff;border:1px solid var(--line);border-radius:14px;box-shadow:0 7px 20px rgba(15,45,80,.04)}.hero{display:grid;grid-template-columns:1.5fr auto;gap:18px;align-items:center;margin-bottom:10px}.hero h1{font-size:25px;margin:0 0 4px}.hero p{margin:0;color:#718096;font-size:12px}.chips{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.chip{background:#fff;border:1px solid var(--line);border-radius:11px;padding:8px 10px;font-size:10px}.status{padding:11px 15px;display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;gap:12px;margin-bottom:10px}.label{font-size:8px;color:#8795a8;text-transform:uppercase;letter-spacing:.25px}.status b{font-size:11px;display:block;margin-top:3px}.actions{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-bottom:10px}.action{padding:11px 12px;text-decoration:none;color:var(--navy);display:flex;gap:9px;align-items:center;min-height:62px}.action i{font-style:normal;width:31px;height:31px;border-radius:9px;background:#eef6ff;color:var(--blue);display:grid;place-items:center;font-weight:bold}.action b{font-size:10px}.action small{display:block;color:var(--muted);font-size:8px;margin-top:3px}.emergency{background:var(--red);color:#fff;border-color:var(--red)}.emergency i{background:#ffffff22;color:#fff}.emergency small{color:#ffe5e9}.attention{padding:10px 14px;border-left:4px solid var(--green);margin-bottom:10px;display:flex;justify-content:space-between;align-items:center}.attention.warn{border-left-color:var(--amber)}.attention b{font-size:11px}.attention small{display:block;color:var(--muted);font-size:9px;margin-top:3px}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:10px}.kpi{padding:12px;min-height:90px;position:relative;text-decoration:none;color:inherit}.kpi:before{content:'';position:absolute;left:0;top:12px;width:3px;height:27px;background:var(--blue)}.kpi.red:before{background:var(--red)}.kpi b{font-size:21px;display:block;margin:8px 0 4px}.kpi small{color:var(--muted);font-size:8px}.grid2{display:grid;grid-template-columns:minmax(0,1.72fr) minmax(320px,.88fr);gap:10px;margin-bottom:10px}.section{padding:14px}.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:11px}.head h2{font-size:12px;margin:0}.head a{font-size:8px;color:#0878d1;text-decoration:none}.journey{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:0;align-items:stretch}.stage{position:relative;background:#f8fafc;border:1px solid #e7edf5;padding:10px 7px;text-decoration:none;color:inherit;min-height:66px}.stage:first-child{border-radius:9px 0 0 9px}.stage:last-child{border-radius:0 9px 9px 0}.stage:not(:last-child):after{content:'›';position:absolute;right:-6px;top:22px;z-index:2;width:12px;height:20px;display:grid;place-items:center;background:#fff;color:var(--blue);font-weight:bold}.stage.active{background:#f1f8ff;border-top:3px solid var(--blue)}.stage.wait{border-top:3px solid var(--amber)}.stage b{font-size:16px}.stage span{display:block;color:var(--muted);font-size:8px;margin-top:5px}.row{display:flex;gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid #edf1f6}.dot{width:7px;height:7px;border-radius:50%;background:var(--red);flex:none}.row div{min-width:0;flex:1}.row b{font-size:9px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row small{color:var(--muted);font-size:8px}.badge{font-size:8px;background:#fff0f2;color:var(--red);padding:4px 7px;border-radius:10px}.reason{color:#9b6a11!important}.lower,.commercial{display:grid;grid-template-columns:1.15fr 1fr;gap:10px;margin-bottom:10px}.commercial{grid-template-columns:1fr 1fr}.asset{display:grid;grid-template-columns:105px 1fr;gap:12px;align-items:center}.ring{width:88px;height:88px;border:12px solid var(--green);border-radius:50%;display:grid;place-items:center;text-align:center}.ring b{font-size:20px}.minis{display:grid;grid-template-columns:1fr 1fr;gap:6px}.mini{background:#f7f9fc;border:1px solid #e7edf5;border-radius:9px;padding:9px}.mini b{font-size:15px}.mini span{display:block;color:var(--muted);font-size:8px;margin-top:4px}.empty{min-height:72px;border:1px dashed #dbe5ef;border-radius:10px;background:#fafcff;display:grid;place-items:center;text-align:center;color:var(--muted);font-size:9px;padding:12px}.activity .dot{background:var(--blue)}.activity .row{position:relative}.footer{text-align:right;color:#8a98aa;font-size:8px;margin-top:6px}@media(max-width:1180px){.journey{grid-template-columns:repeat(4,1fr);gap:6px}.stage{border-radius:8px!important}.stage:after{display:none!important}}@media(max-width:1050px){.actions{grid-template-columns:repeat(2,1fr)}.kpis{grid-template-columns:repeat(3,1fr)}.status{grid-template-columns:1fr 1fr}.grid2,.lower,.commercial{grid-template-columns:1fr}}@media(max-width:620px){.wrap{padding:12px}.hero{display:block}.chips{justify-content:flex-start;margin-top:9px}.actions,.kpis,.status,.journey,.minis{grid-template-columns:1fr}}
